    oranges:{name:"Oranges & Browns",short:"Oranges",noun:"orange",text:"A warm, inviting range of orange and golden hues, from soft peach to deep amber. Apricot, honey and pale gold glow softly, burnt orange, caramel and chestnut add depth, and tangerine and marigold bring energy. There are not many oranges or browns a Spring must avoid.",avoid:[]},
    pinks:{name:"Pinks & Reds",short:"Pinks",noun:"pink or red",text:"Vibrant reds and pinks, bold and soft. Cherry red and crimson add drama, coral, salmon and peach feel fresh and lively, and rose, bubblegum and blush pinks give a softer, romantic touch.",avoid:["#f0a8de", "#e185d1", "#e185b2"]},
    greens:{name:"Greens & Yellows",short:"Greens",noun:"green or yellow",text:"Greens from fresh lime and chartreuse to grass green and olive, with jade and turquoise for depth. Your yellows are sunny and clear, from butter to golden yellow.",avoid:["#fafaa9", "#03501f", "#3b8686", "#cecf80"]},
    blues:{name:"Blues & Purples",short:"Blues",noun:"blue or purple",text:"Clear, bright blues from cobalt to sky, and purples from soft lavender and lilac to royal purple and rich violet. Periwinkle and blue-violets keep the range lively.",avoid:["#60a4ff", "#2542ff", "#a688c4", "#869ecd"]},
