  avoidText:"Cool, muted colours like soft blues, dusty pinks and greys dull your vibrant, warm features. They clash with your bright, fresh colouring and can overwhelm your natural clarity.",
  whyNot:function(hex,hsl){const{h,s,l}=hsl(hex);const r=[];
    if(l<.2)r.push("too dark and heavy for your bright colouring");
    if(s<.42&&l>=.2&&l<=.9)r.push("too muted and dusty, where your colours are clear and bright");
    if(h>=185&&h<345&&s<.8&&l>=.2&&l<=.9)r.push("too cool, with a blue or grey base");
    if(l>.85&&s<.6)r.push("too pale and icy for your warm colouring");
    if(!r.length)r.push("too cool and icy next to your warm, clear palette");
    return r.slice(0,2).join(", and ")},
